1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
net: spacemit: Fix error handling in emac_tx_mem_map()

The DMA mappings were leaked on mapping error. Free them with the
existing emac_free_tx_buf() function.

Fixes: bfec6d7f2001 ("net: spacemit: Add K1 Ethernet MAC")
Signed-off-by: Vivian Wang <wangruikang@iscas.ac.cn>
Link: https://patch.msgid.link/20260305-k1-ethernet-more-fixes-v2-2-e4e434d65055@iscas.ac.cn
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In emac_tx_mem_map(), when a DMA mapping error occurs for a fragment, the error handling path frees the skb but does not free already mapped DMA buffers, causing DMA mapping leaks.

Here is the patch:

 static void emac_tx_mem_map(struct emac_priv *priv, struct sk_buff *skb)
 {
 	struct emac_desc_ring *tx_ring = &priv->tx_ring;
 	struct emac_desc tx_desc, *tx_desc_addr;
 	struct device *dev = &priv->pdev->dev;
 	struct emac_tx_desc_buffer *tx_buf;
-	u32 head, old_head, frag_num, f;
+	u32 head, old_head, frag_num, f, i;
 	bool buf_idx;

 	frag_num = skb_shinfo(skb)->nr_frags;
 	head = tx_ring->head;
 	old_head = head;

 	for (f = 0; f < frag_num + 1; f++) {
 		buf_idx = f % 2;

 		/*
 		 * If using buffer 1, initialize a new desc. Otherwise, use
 		 * buffer 2 of previous fragment's desc.
 		 */
 		if (!buf_idx) {
 			tx_buf = &tx_ring->tx_desc_buf[head];
 			tx_desc_addr =
 				&((struct emac_desc *)tx_ring->desc_addr)[head];
 			memset(&tx_desc, 0, sizeof(tx_desc));

 			/*
 			 * Give ownership for all but first desc initially. For
 			 * first desc, give at the end so DMA cannot start
 			 * reading uninitialized descs.
 			 */
 			if (head != old_head)
 				tx_desc.desc0 |= TX_DESC_0_OWN;

 			if (++head == tx_ring->total_cnt) {
 				/* Just used last desc in ring */
 				tx_desc.desc1 |= TX_DESC_1_END_RING;
 				head = 0;
 			}
 		}

 		if (emac_tx_map_frag(dev, &tx_desc, tx_buf, skb, f)) {
 			dev_err_ratelimited(&priv->ndev->dev,
 					    "Map TX frag %d failed\n", f);
 			goto err_free_skb;
 		}

 		if (f == 0)
 			tx_desc.desc1 |= TX_DESC_1_FIRST_SEGMENT;

 		if (f == frag_num) {
 			tx_desc.desc1 |= TX_DESC_1_LAST_SEGMENT;
 			tx_buf->skb = skb;
 			if (emac_tx_should_interrupt(priv, frag_num + 1))
 				tx_desc.desc1 |=
 					TX_DESC_1_INTERRUPT_ON_COMPLETION;
 		}

 		*tx_desc_addr = tx_desc;
 	}

 	/* All descriptors are ready, give ownership for first desc */
 	tx_desc_addr = &((struct emac_desc *)tx_ring->desc_addr)[old_head];
 	dma_wmb();
 	WRITE_ONCE(tx_desc_addr->desc0, tx_desc_addr->desc0 | TX_DESC_0_OWN);

 	emac_dma_start_transmit(priv);

 	tx_ring->head = head;

 	return;

 err_free_skb:
 	dev_dstats_tx_dropped(priv->ndev);
+
+	i = old_head;
+	while (i != head) {
+		emac_free_tx_buf(priv, i);
+
+		if (++i == tx_ring->total_cnt)
+			i = 0;
+	}
+
 	dev_kfree_skb_any(skb);
 }



